// ═══════════════════════════════════════════════
// AGENTGUARD — RetryClassifier v1.0
// 10-class error taxonomy with specific recovery
// ═══════════════════════════════════════════════

const config = {
  maxRetries: 5,
  baseDelay: 500,
  maxDelay: 32000,
  jitterRatio: 0.25,
  fallbackModel: 'gemma4:e4b',
  fallbackEndpoint: 'http://localhost:11434/v1/chat/completions',
  persistentRetry: false,
  persistentMaxDelay: 300000,
  consecutiveOverloadThreshold: 3
};

const input = $input.first().json;
const statusCode = input.statusCode || input.status || 0;
const headers = input.headers || {};
const body = input.body || input.error || {};
const attempt = input._agRetryAttempt || 0;
const consecutive529 = input._ag529Count || 0;
const errorMessage = typeof body === 'string' ? body : (body.error?.message || body.message || '');

// ─── Classification Engine ───
function classify(code, headers, body, errorMsg) {
  // Rate Limited
  if (code === 429) {
    const retryAfter = parseInt(headers['retry-after'] || '0');
    const isOverage = headers['x-overage-disabled'] === 'true';
    if (isOverage) return { class: 'quota_exceeded', retryAfter, permanent: true };
    if (retryAfter > 20) return { class: 'rate_limited_long', retryAfter };
    return { class: 'rate_limited', retryAfter: retryAfter || 2 };
  }

  // Server Overload
  if (code === 529 || code === 503) {
    return { class: 'server_overload', consecutive: consecutive529 + 1 };
  }

  // Context Overflow
  if (code === 400 && (errorMsg.includes('context') || errorMsg.includes('token') || errorMsg.includes('too long') || errorMsg.includes('max_tokens'))) {
    const match = errorMsg.match(/(\d+)\s*(?:tokens|token)/);
    const actualTokens = match ? parseInt(match[1]) : null;
    return { class: 'context_overflow', actualTokens };
  }

  // Input Validation
  if (code === 400 || code === 422) {
    return { class: 'input_validation', noRetry: true };
  }

  // Auth Failure
  if (code === 401 || code === 403) {
    return { class: 'auth_failure' };
  }

  // Network Errors
  if (code === 0 || errorMsg.includes('ECONNRESET') || errorMsg.includes('EPIPE') || errorMsg.includes('timeout') || errorMsg.includes('ETIMEDOUT')) {
    return { class: 'network_error' };
  }

  // Streaming Stall (custom detection)
  if (errorMsg.includes('stream') && errorMsg.includes('stall')) {
    return { class: 'streaming_stall' };
  }

  return { class: 'unknown' };
}

// ─── Recovery Engine ───
function getRecovery(classification, attempt) {
  const backoff = Math.min(config.baseDelay * Math.pow(2, attempt), config.maxDelay);
  const jitter = Math.random() * config.jitterRatio * backoff;
  const delay = Math.round(backoff + jitter);

  switch (classification.class) {
    case 'rate_limited':
      return {
        action: 'retry',
        delay: classification.retryAfter * 1000,
        switchModel: false,
        message: `Rate limited. Waiting ${classification.retryAfter}s (from Retry-After header).`
      };

    case 'rate_limited_long':
      return {
        action: 'retry',
        delay: Math.min(classification.retryAfter * 1000, 1800000),
        switchModel: false,
        message: `Long rate limit: ${classification.retryAfter}s. Entering cooldown.`
      };

    case 'quota_exceeded':
      return {
        action: 'switch_model',
        delay: 0,
        switchModel: true,
        targetModel: config.fallbackModel,
        targetEndpoint: config.fallbackEndpoint,
        permanent: true,
        message: 'Quota exceeded. Permanently switching to fallback model.'
      };

    case 'server_overload':
      if (classification.consecutive >= config.consecutiveOverloadThreshold) {
        return {
          action: 'switch_model',
          delay: 0,
          switchModel: true,
          targetModel: config.fallbackModel,
          targetEndpoint: config.fallbackEndpoint,
          message: `${classification.consecutive} consecutive 529s. Switching to fallback.`
        };
      }
      return {
        action: 'retry',
        delay,
        switchModel: false,
        message: `Server overloaded (${classification.consecutive}/${config.consecutiveOverloadThreshold} before fallback). Backoff ${delay}ms.`
      };

    case 'context_overflow':
      return {
        action: 'compact_and_retry',
        delay: 0,
        switchModel: false,
        compactionNeeded: true,
        actualTokens: classification.actualTokens,
        message: 'Context overflow. Triggering compaction before retry.'
      };

    case 'auth_failure':
      return {
        action: attempt === 0 ? 'refresh_and_retry' : 'fail',
        delay: 0,
        switchModel: false,
        clearCache: true,
        message: attempt === 0 ? 'Auth failed. Clearing cache, refreshing token.' : 'Auth failed after refresh. Escalating.'
      };

    case 'network_error':
      return {
        action: 'retry',
        delay,
        switchModel: false,
        disableKeepAlive: true,
        message: `Network error. Fresh connection. Backoff ${delay}ms.`
      };

    case 'streaming_stall':
      return {
        action: 'retry_non_streaming',
        delay: 0,
        switchModel: false,
        disableStreaming: true,
        message: 'Stream stalled. Retrying with non-streaming request.'
      };

    case 'input_validation':
      return {
        action: 'fail',
        delay: 0,
        switchModel: false,
        message: `Validation error: ${errorMessage}. No retry — fix input.`
      };

    default:
      return {
        action: attempt < config.maxRetries ? 'retry' : 'fail',
        delay,
        switchModel: false,
        message: `Unknown error (${statusCode}). ${attempt < config.maxRetries ? `Retry ${attempt + 1}/${config.maxRetries}.` : 'Max retries. Failing.'}`
      };
  }
}

// ─── Execute ───
const classification = classify(statusCode, headers, body, errorMessage);
const recovery = getRecovery(classification, attempt);

const shouldRetry = recovery.action !== 'fail' && attempt < config.maxRetries;

return [{
  json: {
    // Classification
    errorClass: classification.class,
    statusCode,

    // Recovery decision
    action: recovery.action,
    shouldRetry,
    delay: recovery.delay,
    message: recovery.message,

    // Model switching
    switchModel: recovery.switchModel || false,
    targetModel: recovery.targetModel || null,
    targetEndpoint: recovery.targetEndpoint || null,

    // Flags
    compactionNeeded: recovery.compactionNeeded || false,
    disableKeepAlive: recovery.disableKeepAlive || false,
    disableStreaming: recovery.disableStreaming || false,
    clearAuthCache: recovery.clearCache || false,
    permanent: recovery.permanent || false,

    // State tracking
    _agRetryAttempt: attempt + 1,
    _ag529Count: classification.class === 'server_overload' ? (consecutive529 + 1) : 0,

    // Audit
    _agTimestamp: new Date().toISOString(),
    _agInput: input
  }
}];
